function norm(s) {
  return typeof s === "string" ? s.trim() : "";
}

function parseRepo(input) {
  const raw = norm(input);
  if (!raw) return null;

  // Supported:
  // - owner/repo
  // - https://github.com/owner/repo
  // - git@github.com:owner/repo.git
  let owner = "";
  let repo = "";

  const m1 = raw.match(/^([A-Za-z0-9_.-]+)\/([A-Za-z0-9_.-]+)$/);
  if (m1) {
    owner = m1[1];
    repo = m1[2];
    return { owner, repo, source: "owner_repo" };
  }

  const m2 = raw.match(/^https?:\/\/github\.com\/([^/]+)\/([^/#?]+)(?:[/?#].*)?$/i);
  if (m2) {
    owner = m2[1];
    repo = m2[2].replace(/\.git$/i, "");
    return { owner, repo, source: "github_url" };
  }

  const m3 = raw.match(/^git@github\.com:([^/]+)\/([^/]+?)(?:\.git)?$/i);
  if (m3) {
    owner = m3[1];
    repo = m3[2].replace(/\.git$/i, "");
    return { owner, repo, source: "git_ssh" };
  }

  return null;
}

export default {
  async main(env, ctx) {
    const p = ctx?.params || {};

    const repoInput = p.repo;
    const ref = norm(p.ref) || "";

    const parsed = parseRepo(repoInput);

    const meta = {
      parsedAt: new Date().toISOString(),
      errors: [],
      warnings: [],
      input: { repo: repoInput, ref: ref || null },
    };

    if (!parsed) {
      meta.errors.push(
        'Failed to parse repo: please provide "owner/repo" or "https://github.com/owner/repo"(also supports git@github.com:owner/repo.git)',
      );
      return {
        outputs: {
          ok: false,
          owner: "",
          repo: "",
          ref: ref || null,
          repo_url: null,
          api_base: null,
          raw_base: null,
          meta,
        },
      };
    }

    const owner = parsed.owner;
    const repo = parsed.repo;

    const repo_url = `https://github.com/${encodeURIComponent(owner)}/${encodeURIComponent(repo)}`;
    const api_base = `https://api.github.com/repos/${encodeURIComponent(owner)}/${encodeURIComponent(repo)}`;
    const raw_base = `https://raw.githubusercontent.com/${encodeURIComponent(owner)}/${encodeURIComponent(repo)}`;

    return {
      outputs: {
        ok: true,
        owner,
        repo,
        ref: ref || null,
        repo_url,
        api_base,
        raw_base,
        meta,
      },
    };
  },
};

function authHeaders(env) {
  const token = typeof env?.GITHUB_TOKEN === "string" ? env.GITHUB_TOKEN.trim() : "";
  return token ? { Authorization: `Bearer ${token}` } : {};
}

async function fetchJson(url, timeoutMs, headers) {
  const controller = new AbortController();
  const t = setTimeout(() => controller.abort(), Math.max(1, Number(timeoutMs) || 15000));
  try {
    const res = await fetch(url, {
      signal: controller.signal,
      headers: {
        "User-Agent": "Mozilla/5.0 (compatible; Maia-Release-Readiness/1.0)",
        Accept: "application/vnd.github+json",
        ...headers,
      },
    });
    const text = await res.text();
    let json = null;
    try {
      json = text ? JSON.parse(text) : null;
    } catch {
      json = null;
    }
    return { res, json, text };
  } finally {
    clearTimeout(t);
  }
}

export default {
  async main(env, ctx) {
    const upstream = ctx?.upstream || {};
    const p = ctx?.params || {};

    const norm = upstream.normalize_repo?.data;
    const apiBase = String(norm?.outputs?.api_base || "");
    const ref = typeof norm?.outputs?.ref === "string" ? norm.outputs.ref : null;

    const timeoutMs = Number(p.timeoutMs ?? 15000) || 15000;

    const meta = {
      fetchedAt: new Date().toISOString(),
      timeoutMs,
      errors: [],
      warnings: [],
      rateLimit: null,
    };

    if (!apiBase) {
      meta.errors.push("missing api_base from upstream.normalize_repo");
      return { outputs: { repo: null, meta } };
    }

    const url = apiBase;

    try {
      const { res, json, text } = await fetchJson(url, timeoutMs, authHeaders(env));

      // Rate limit info (best effort)
      const rl = {
        limit: res.headers.get("x-ratelimit-limit"),
        remaining: res.headers.get("x-ratelimit-remaining"),
        reset: res.headers.get("x-ratelimit-reset"),
      };
      meta.rateLimit = rl;

      if (!res.ok || !json) {
        meta.errors.push(`GitHub API failed: HTTP ${res.status} ${res.statusText}`);
        if (text && text.length < 500) meta.warnings.push(`body: ${text}`);
        return { outputs: { repo: null, meta } };
      }

      const repo = {
        id: json.id ?? null,
        full_name: typeof json.full_name === "string" ? json.full_name : null,
        description: typeof json.description === "string" ? json.description : null,
        html_url: typeof json.html_url === "string" ? json.html_url : null,
        default_branch: typeof json.default_branch === "string" ? json.default_branch : null,
        visibility: typeof json.visibility === "string" ? json.visibility : null,
        private: Boolean(json.private),
        archived: Boolean(json.archived),
        disabled: Boolean(json.disabled),
        fork: Boolean(json.fork),
        stargazers_count: typeof json.stargazers_count === "number" ? json.stargazers_count : null,
        forks_count: typeof json.forks_count === "number" ? json.forks_count : null,
        open_issues_count: typeof json.open_issues_count === "number" ? json.open_issues_count : null,
        license: json.license && typeof json.license === "object" ? { spdx_id: json.license.spdx_id ?? null, name: json.license.name ?? null } : null,
        homepage: typeof json.homepage === "string" ? json.homepage : null,
        topics: Array.isArray(json.topics) ? json.topics.filter((x) => typeof x === "string") : [],
      };

      // If user didn't set ref, we recommend default_branch
      const effectiveRef = ref || repo.default_branch || null;
      if (!effectiveRef) meta.warnings.push("Cannot determine ref (ref not provided and repo.default_branch is missing)");

      return { outputs: { repo, effective_ref: effectiveRef, meta } };
    } catch (e) {
      const name = e && typeof e === "object" && "name" in e ? String(e.name) : "";
      const msg = e instanceof Error ? e.message : String(e);
      meta.errors.push(name === "AbortError" ? `timeout: ${msg}` : msg);
      return { outputs: { repo: null, effective_ref: null, meta } };
    }
  },
};

function authHeaders(env) {
  const token = typeof env?.GITHUB_TOKEN === "string" ? env.GITHUB_TOKEN.trim() : "";
  return token ? { Authorization: `Bearer ${token}` } : {};
}

