export default {
  async main(env, ctx) {
    const upstream = ctx?.upstream || {};
    const p = ctx?.params || {};

    const norm = upstream.normalize_repo?.data;
    const apiBase = String(norm?.outputs?.api_base || "");

    const timeoutMs = Number(p.timeoutMs ?? 15000) || 15000;

    const meta = {
      fetchedAt: new Date().toISOString(),
      timeoutMs,
      errors: [],
      warnings: [],
      rateLimit: null,
    };

    if (!apiBase) {
      meta.errors.push("missing api_base from upstream.normalize_repo");
      return { outputs: { latest_release: null, latest_tag: null, meta } };
    }

    try {
      // latest release (may 404 if no releases)
      const relUrl = `${apiBase}/releases/latest`;
      const { res: resRel, json: relJson, text: relText } = await fetchJson(relUrl, timeoutMs, authHeaders(env));

      meta.rateLimit = {
        limit: resRel.headers.get("x-ratelimit-limit"),
        remaining: resRel.headers.get("x-ratelimit-remaining"),
        reset: resRel.headers.get("x-ratelimit-reset"),
      };

      let latest_release = null;
      if (resRel.ok && relJson) {
        latest_release = {
          tag_name: typeof relJson.tag_name === "string" ? relJson.tag_name : null,
          name: typeof relJson.name === "string" ? relJson.name : null,
          draft: Boolean(relJson.draft),
          prerelease: Boolean(relJson.prerelease),
          html_url: typeof relJson.html_url === "string" ? relJson.html_url : null,
          published_at: typeof relJson.published_at === "string" ? relJson.published_at : null,
        };
      } else if (resRel.status === 404) {
        meta.warnings.push("Repo has no GitHub Releases (/releases/latest returned 404)");
      } else {
        meta.warnings.push(`latest release request failed: HTTP ${resRel.status} ${resRel.statusText}`);
        if (relText && relText.length < 500) meta.warnings.push(`body: ${relText}`);
      }

      // tags (first page, newest first)
      const tagsUrl = `${apiBase}/tags?per_page=1`;
      const { res: resTags, json: tagsJson, text: tagsText } = await fetchJson(tagsUrl, timeoutMs, authHeaders(env));

      let latest_tag = null;
      if (resTags.ok && Array.isArray(tagsJson) && tagsJson.length) {
        const t0 = tagsJson[0];
        latest_tag = {
          name: typeof t0?.name === "string" ? t0.name : null,
          commit_sha: typeof t0?.commit?.sha === "string" ? t0.commit.sha : null,
        };
      } else {
        meta.warnings.push(`tags request failed or empty: HTTP ${resTags.status} ${resTags.statusText}`);
        if (tagsText && tagsText.length < 500) meta.warnings.push(`body: ${tagsText}`);
      }

      return { outputs: { latest_release, latest_tag, meta } };
    } catch (e) {
      const name = e && typeof e === "object" && "name" in e ? String(e.name) : "";
      const msg = e instanceof Error ? e.message : String(e);
      meta.errors.push(name === "AbortError" ? `timeout: ${msg}` : msg);
      return { outputs: { latest_release: null, latest_tag: null, meta } };
    }
  },
};

function authHeaders(env) {
  const token = typeof env?.GITHUB_TOKEN === "string" ? env.GITHUB_TOKEN.trim() : "";
  return token ? { Authorization: `Bearer ${token}` } : {};
}

