function encQ(s) {
  return encodeURIComponent(String(s || "").trim());
}

export default {
  async main(env, ctx) {
    const upstream = ctx?.upstream || {};
    const p = ctx?.params || {};

    const norm = upstream.normalize_repo?.data;
    const owner = String(norm?.outputs?.owner || "");
    const repo = String(norm?.outputs?.repo || "");

    const timeoutMs = Number(p.timeoutMs ?? 15000) || 15000;

    const meta = {
      fetchedAt: new Date().toISOString(),
      timeoutMs,
      errors: [],
      warnings: [],
      rateLimit: null,
    };

    if (!owner || !repo) {
      meta.errors.push("missing owner/repo from upstream.normalize_repo");
      return { outputs: { stats: null, meta } };
    }

    // Real-world, opinionated queries for OSS release readiness
    const repoQualifier = `repo:${owner}/${repo}`;
    const queries = {
      open_pr: `${repoQualifier} is:pr is:open`,
      open_issue: `${repoQualifier} is:issue is:open`,
      release_blocker: `${repoQualifier} is:issue is:open label:release-blocker`,
      security: `${repoQualifier} is:issue is:open label:security`,
      bug: `${repoQualifier} is:issue is:open label:bug`,
      good_first_issue: `${repoQualifier} is:issue is:open label:"good first issue"`,
    };

    try {
      const stats = {};
      for (const [k, q] of Object.entries(queries)) {
        const url = `https://api.github.com/search/issues?q=${encQ(q)}&per_page=1`;
        const { res, json, text } = await fetchJson(url, timeoutMs, authHeaders(env));

        meta.rateLimit = {
          limit: res.headers.get("x-ratelimit-limit"),
          remaining: res.headers.get("x-ratelimit-remaining"),
          reset: res.headers.get("x-ratelimit-reset"),
        };

        if (!res.ok || !json) {
          meta.warnings.push(`query ${k} failed: HTTP ${res.status} ${res.statusText}`);
          if (text && text.length < 300) meta.warnings.push(`body: ${text}`);
          stats[k] = null;
          continue;
        }

        stats[k] = typeof json.total_count === "number" ? json.total_count : null;
      }

      return {
        outputs: {
          stats,
          meta,
        },
      };
    } catch (e) {
      const name = e && typeof e === "object" && "name" in e ? String(e.name) : "";
      const msg = e instanceof Error ? e.message : String(e);
      meta.errors.push(name === "AbortError" ? `timeout: ${msg}` : msg);
      return { outputs: { stats: null, meta } };
    }
  },
};

function norm(s) {
  return typeof s === "string" ? s.trim() : "";
}

async function fetchText(url, timeoutMs, headers) {
  const controller = new AbortController();
  const t = setTimeout(() => controller.abort(), Math.max(1, Number(timeoutMs) || 15000));
  try {
    const res = await fetch(url, {
      signal: controller.signal,
      headers: {
        "User-Agent": "Mozilla/5.0 (compatible; Maia-Release-Readiness/1.0)",
        Accept: "text/plain,*/*",
        ...headers,
      },
    });
    const text = await res.text();
    return { res, text };
  } finally {
    clearTimeout(t);
  }
}

function authHeaders(env) {
  // For raw.githubusercontent.com, token is usually not needed; but we still pass it as best-effort.
  const token = typeof env?.GITHUB_TOKEN === "string" ? env.GITHUB_TOKEN.trim() : "";
  return token ? { Authorization: `Bearer ${token}` } : {};
}

export default {
  async main(env, ctx) {
    const upstream = ctx?.upstream || {};
    const p = ctx?.params || {};

    const normUp = upstream.normalize_repo?.data;
    const rawBase = String(normUp?.outputs?.raw_base || "");

    const repoMeta = upstream.fetch_repo_meta?.data;
    const effectiveRef = repoMeta?.outputs?.effective_ref || normUp?.outputs?.ref || "main";

    const timeoutMs = Number(p.timeoutMs ?? 15000) || 15000;

    const meta = {
      fetchedAt: new Date().toISOString(),
      timeoutMs,
      errors: [],
      warnings: [],
      effectiveRef,
    };

    if (!rawBase) {
      meta.errors.push("missing raw_base from upstream.normalize_repo");
      return { outputs: { files: [], meta } };
    }

    const paths = Array.isArray(p.docPaths) && p.docPaths.length
      ? p.docPaths
      : ["README.md", "CHANGELOG.md", "CONTRIBUTING.md", "SECURITY.md", "CODE_OF_CONDUCT.md", "LICENSE"];

    const results = [];

    for (const relPath0 of paths) {
      const relPath = norm(relPath0);
      if (!relPath) continue;

      const url = `${rawBase}/${encodeURIComponent(String(effectiveRef))}/${relPath.replace(/^\/+/, "")}`;
      try {
        const { res, text } = await fetchText(url, timeoutMs, authHeaders(env));
        if (!res.ok) {
          results.push({
            kind: "repo_file",
            path: relPath,
            url,
            ok: false,
            status: res.status,
            text: "",
          });
          continue;
        }

        // Hard cap: avoid huge binary or massive docs
        const capped = text.length > 300_000 ? text.slice(0, 300_000) : text;
        if (text.length > 300_000) meta.warnings.push(`${relPath} too large; truncated to 300k chars`);

        results.push({
          kind: "repo_file",
          path: relPath,
          url,
          ok: true,
          status: res.status,
          text: capped,
        });
      } catch (e) {
        const name = e && typeof e === "object" && "name" in e ? String(e.name) : "";
        const msg = e instanceof Error ? e.message : String(e);
        results.push({
          kind: "repo_file",
          path: relPath,
          url,
          ok: false,
          status: 0,
          text: "",
          error: name === "AbortError" ? `timeout: ${msg}` : msg,
        });
      }
    }

    // Summarize presence
    const present = results.filter((x) => x.ok).map((x) => x.path);
    if (!present.includes("README.md")) meta.warnings.push("README.md not fetched (may not be root README.md or repo uses README.rst etc.)");

    return {
      outputs: {
        files: results,
        meta,
      },
    };
  },
};

async function fetchText(url, timeoutMs) {
  const controller = new AbortController();
  const t = setTimeout(() => controller.abort(), Math.max(1, Number(timeoutMs) || 15000));
  try {
    const res = await fetch(url, {
      signal: controller.signal,
      headers: {
        "User-Agent": "Mozilla/5.0 (compatible; Maia-Release-Readiness/1.0)",
        Accept: "application/json,text/plain,*/*",
      },
    });
    const text = await res.text();
    return { res, text };
  } finally {
    clearTimeout(t);
  }
}

export default {
  async main(env, ctx) {
    const upstream = ctx?.upstream || {};
    const p = ctx?.params || {};

    const normUp = upstream.normalize_repo?.data;
    const rawBase = String(normUp?.outputs?.raw_base || "");

    const repoMeta = upstream.fetch_repo_meta?.data;
    const effectiveRef = repoMeta?.outputs?.effective_ref || normUp?.outputs?.ref || "main";

    const timeoutMs = Number(p.timeoutMs ?? 15000) || 15000;

    const meta = {
      fetchedAt: new Date().toISOString(),
      timeoutMs,
      effectiveRef,
      errors: [],
      warnings: [],
    };

    if (!rawBase) {
      meta.errors.push("missing raw_base from upstream.normalize_repo");
      return { outputs: { ok: false, exists: false, package_json: null, meta } };
    }

    const url = `${rawBase}/${encodeURIComponent(String(effectiveRef))}/package.json`;

    try {
      const { res, text } = await fetchText(url, timeoutMs);

      if (res.status === 404) {
        return { outputs: { ok: true, exists: false, package_json: null, meta } };
      }

      if (!res.ok) {
        meta.warnings.push(`package.json fetch failed: HTTP ${res.status} ${res.statusText}`);
        return { outputs: { ok: false, exists: false, package_json: null, meta } };
      }

      let obj = null;
      try {
        obj = text ? JSON.parse(text) : null;
      } catch (e) {
        meta.warnings.push(`package.json parse failed: ${e instanceof Error ? e.message : String(e)}`);
        obj = null;
      }

      const isObj = !!obj && typeof obj === "object" && !Array.isArray(obj);
      if (!isObj) {
        meta.warnings.push("package.json is not an object");
      }

      return {
        outputs: {
          ok: true,
          exists: true,
          package_json: isObj ? obj : null,
          meta,
        },
      };
    } catch (e) {
      const name = e && typeof e === "object" && "name" in e ? String(e.name) : "";
      const msg = e instanceof Error ? e.message : String(e);
      meta.errors.push(name === "AbortError" ? `timeout: ${msg}` : msg);
      return { outputs: { ok: false, exists: false, package_json: null, meta } };
    }
  },
};

function isStr(v) {
  return typeof v === "string" && v.trim().length > 0;
}

function isObj(v) {
  return !!v && typeof v === "object" && !Array.isArray(v);
}

function pickRepoUrl(repository) {
  if (!repository) return null;
  if (typeof repository === "string") return repository.trim() || null;
  if (typeof repository === "object" && repository && typeof repository.url === "string") return repository.url.trim() || null;
  return null;
}

export default {
  async main(env, ctx) {
    const upstream = ctx?.upstream || {};

    const pkgUp = upstream.fetch_package_json?.data;
    const pkg = pkgUp?.outputs?.package_json;
    const exists = Boolean(pkgUp?.outputs?.exists);

    const meta = {
      analyzedAt: new Date().toISOString(),
      errors: [],
      warnings: [],
    };

    if (!exists) {
      meta.warnings.push("repo root has no package.json: will skip npm publish-related checks");
      return { outputs: { exists: false, checks: [], summary: { ok: true, score: 0 }, meta } };
    }

    if (!isObj(pkg)) {
      meta.errors.push("package.json unavailable (parse failed or not an object)");
      return { outputs: { exists: true, checks: [], summary: { ok: false, score: 0 }, meta } };
    }

    const checks = [];
    const add = (id, title, ok, detail, level) => {
      checks.push({ id, title, ok: Boolean(ok), level: level || (ok ? "info" : "warn"), detail: detail || null });
    };

    add("pkg_name", "name exists", isStr(pkg.name), isStr(pkg.name) ? pkg.name : "missing name", isStr(pkg.name) ? "info" : "error");
    add("pkg_version", "version exists", isStr(pkg.version), isStr(pkg.version) ? pkg.version : "missing version", isStr(pkg.version) ? "info" : "warn");

    // Common OSS metadata
    add("pkg_license", "license exists", isStr(pkg.license), isStr(pkg.license) ? pkg.license : "missing license", isStr(pkg.license) ? "info" : "warn");
    add("pkg_repository", "repository exists", !!pickRepoUrl(pkg.repository), pickRepoUrl(pkg.repository) || "missing repository", pickRepoUrl(pkg.repository) ? "info" : "warn");
    add("pkg_bugs", "bugs field exists (issue link)", !!pkg.bugs, pkg.bugs ? "ok" : "missing bugs", pkg.bugs ? "info" : "warn");
    add("pkg_homepage", "homepage field exists", isStr(pkg.homepage), isStr(pkg.homepage) ? pkg.homepage : "missing homepage", isStr(pkg.homepage) ? "info" : "warn");

    // npm publish readiness
    add("pkg_private", "private !== true (otherwise cannot publish to npm public)", pkg.private !== true, pkg.private === true ? "private=true blocks npm publish" : "ok", pkg.private === true ? "warn" : "info");

    // engines (nice-to-have)
    add("pkg_engines", "engines field exists (recommended)", isObj(pkg.engines), isObj(pkg.engines) ? "ok" : "missing engines", isObj(pkg.engines) ? "info" : "warn");

    // entry points (best effort)
    const hasExports = isObj(pkg.exports);
    const hasMain = isStr(pkg.main);
    const hasTypes = isStr(pkg.types) || isStr(pkg.typings);
    add("pkg_entry", "export entry (exports/main) exists", hasExports || hasMain, hasExports ? "exports" : hasMain ? `main=${pkg.main}` : "missing exports/main", hasExports || hasMain ? "info" : "warn");
    add("pkg_types", "types/typings exists (recommended for TS packages)", hasTypes, hasTypes ? (pkg.types || pkg.typings) : "missing types/typings", hasTypes ? "info" : "warn");

    // score: simple weighted
    const errors = checks.filter((c) => !c.ok && c.level === "error").length;
    const warns = checks.filter((c) => !c.ok && c.level === "warn").length;
    const score = Math.max(0, 100 - errors * 30 - warns * 10);

    return {
      outputs: {
        exists: true,
        checks,
        summary: {
          ok: errors === 0,
          score,
          errors,
          warnings: warns,
        },
        meta,
      },
    };
  },
};

export default {
  async main(env, ctx) {
    const upstream = ctx?.upstream || {};

    const docs = upstream.fetch_repo_docs?.data;
    const repoFiles = Array.isArray(docs?.outputs?.files) ? docs.outputs.files : [];

    const meta = {
      collectedAt: new Date().toISOString(),
      errors: [],
      warnings: [],
      stats: {
        repoFiles: repoFiles.length,
      },
    };

    const sources = [];

    for (const f of repoFiles) {
      if (!f || typeof f !== "object") continue;
      sources.push({
        kind: "repo",
        name: String(f.path || "file"),
        path: String(f.path || ""),
        url: String(f.url || ""),
        ok: Boolean(f.ok),
        text: Boolean(f.ok) ? String(f.text || "") : "",
        status: Number(f.status || 0) || 0,
      });
    }

    return {
      outputs: {
        sources,
        meta,
      },
    };
  },
};

function norm(s) {
  return typeof s === "string" ? s.trim() : "";
}

function uniq(arr) {
  const out = [];
  const seen = new Set();
  for (const x of arr) {
    const k = String(x || "").trim();
    if (!k) continue;
    const key = k.toLowerCase();
    if (seen.has(key)) continue;
    seen.add(key);
    out.push(k);
  }
  return out;
}

function extractFromText(md) {
  const s = String(md || "");
  const urls = [];

  // Markdown links: [text](url)
  const reMd = /\[[^\]]*\]\((https?:\/\/[^)\s]+)\)/g;
  for (const m of s.matchAll(reMd)) urls.push(m[1]);

  // Autolink: <https://...>
  const reAuto = /<(https?:\/\/[^>\s]+)>/g;
  for (const m of s.matchAll(reAuto)) urls.push(m[1]);

  // Bare URLs
  const reBare = /(https?:\/\/[^\s)\]"'<>]+)[\s)\]"'<>]?/g;
  for (const m of s.matchAll(reBare)) urls.push(m[1]);

  return urls;
}

export default {
  async main(env, ctx) {
    const upstream = ctx?.upstream || {};
    const p = ctx?.params || {};

    const collected = upstream.collect_markdown_sources?.data;
    const sources = Array.isArray(collected?.outputs?.sources) ? collected.outputs.sources : [];

    const maxLinks = Number(p.maxLinks ?? 120) || 120;

    const meta = {
      extractedAt: new Date().toISOString(),
      errors: [],
      warnings: [],
      maxLinks,
      stats: {
        sources: sources.length,
        rawLinks: 0,
        uniqueLinks: 0,
        truncated: false,
        ignoredNonHttp: 0,
      },
    };

    const all = [];
    for (const src of sources) {
      if (!src || typeof src !== "object") continue;
      const text = String(src.text || "");
      const links = extractFromText(text);
      meta.stats.rawLinks += links.length;
      for (const u of links) all.push(u);
    }

    const unique = uniq(all);

    const httpOnly = [];
    for (const u of unique) {
      const s = norm(u);
      if (!s) continue;
      if (!/^https?:\/\//i.test(s)) {
        meta.stats.ignoredNonHttp += 1;
        continue;
      }
      // strip trailing punctuation often found in markdown
      const cleaned = s.replace(/[),.;:]+$/g, "");
      httpOnly.push(cleaned);
    }

    const final = httpOnly.slice(0, maxLinks);
    meta.stats.uniqueLinks = httpOnly.length;
    meta.stats.truncated = httpOnly.length > maxLinks;
    if (meta.stats.truncated) meta.warnings.push(`links truncated to maxLinks=${maxLinks}`);

    return {
      outputs: {
        targets: final.map((url) => ({ url })),
        meta,
      },
    };
  },
};

function nowMs() {
  return Date.now();
}

async function withConcurrency(items, concurrency, worker) {
  const arr = Array.isArray(items) ? items : [];
  const c = Math.max(1, Math.min(50, Number(concurrency) || 5));
  const results = new Array(arr.length);
  let idx = 0;

  async function runOne() {
    while (true) {
      const i = idx++;
      if (i >= arr.length) return;
      results[i] = await worker(arr[i], i);
    }
  }

  const pool = new Array(Math.min(c, arr.length)).fill(0).map(() => runOne());
  await Promise.all(pool);
  return results;
}

async function fetchWithTimeout(url, init, timeoutMs) {
  const controller = new AbortController();
  const t = setTimeout(() => controller.abort(), Math.max(1, Number(timeoutMs) || 10000));
  try {
    const res = await fetch(url, { ...init, signal: controller.signal });
    return res;
  } finally {
    clearTimeout(t);
  }
}

export default {
  async main(env, ctx) {
    const upstream = ctx?.upstream || {};
    const p = ctx?.params || {};

    const extracted = upstream.extract_links?.data;
    const targets = Array.isArray(extracted?.outputs?.targets) ? extracted.outputs.targets : [];

    const timeoutMs = Number(p.timeoutMs ?? 10000) || 10000;
    const concurrency = Number(p.concurrency ?? 6) || 6;
    const followRedirects = Boolean(p.followRedirects ?? true);

    const meta = {
      timeoutMs,
      concurrency,
      followRedirects,
      checkedAt: new Date().toISOString(),
      errors: [],
      warnings: [],
    };

    if (!targets.length) {
      meta.warnings.push("no links to check");
      return { outputs: { results: [], meta } };
    }

    const redirect = followRedirects ? "follow" : "manual";

    const results = await withConcurrency(targets, concurrency, async (t) => {
      const url = String(t?.url || "");
      const started = nowMs();

      try {
        const res = await fetchWithTimeout(
          url,
          {
            method: "HEAD",
            redirect,
            headers: {
              "User-Agent": "Mozilla/5.0 (compatible; Maia-Release-Readiness/1.0)",
              Accept: "text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8",
            },
          },
          timeoutMs,
        );

        const latency_ms = nowMs() - started;
        return {
          url,
          method: "HEAD",
          ok: res.status >= 200 && res.status < 400,
          status: res.status,
          final_url: String(res.url || url),
          redirected: Boolean(res.redirected),
          latency_ms,
          error: null,
        };
      } catch (e) {
        const latency_ms = nowMs() - started;
        const msg = e instanceof Error ? e.message : String(e);
        const name = e && typeof e === "object" && "name" in e ? String(e.name) : "";
        const isTimeout = name === "AbortError";
        return {
          url,
          method: "HEAD",
          ok: false,
          status: 0,
          final_url: url,
          redirected: false,
          latency_ms,
          error: isTimeout ? `timeout: ${msg}` : msg,
        };
      }
    });

    return { outputs: { results, meta } };
  },
};

