export default {
  async main(env, ctx) {
    const upstream = ctx?.upstream || {};
    const p = ctx?.params || {};

    const head = upstream.head_check_links?.data;
    const headResults = Array.isArray(head?.outputs?.results) ? head.outputs.results : [];

    const timeoutMs = Number(p.timeoutMs ?? 10000) || 10000;
    const concurrency = Number(p.concurrency ?? 6) || 6;
    const followRedirects = Boolean(p.followRedirects ?? true);

    const meta = {
      timeoutMs,
      concurrency,
      followRedirects,
      fallbackFor: { statuses: [0, 403, 405] },
      checkedAt: new Date().toISOString(),
      errors: [],
      warnings: [],
    };

    if (!headResults.length) {
      meta.warnings.push("HEAD results empty");
      return { outputs: { results_patch: [], meta } };
    }

    const needsFallback = headResults.filter((r) => {
      const status = Number(r?.status || 0) || 0;
      return status === 0 || status === 403 || status === 405;
    });

    if (!needsFallback.length) {
      return { outputs: { results_patch: [], meta } };
    }

    const redirect = followRedirects ? "follow" : "manual";

    const results_patch = await withConcurrency(needsFallback, concurrency, async (r) => {
      const url = String(r?.url || "");
      const started = nowMs();

      try {
        const res = await fetchWithTimeout(
          url,
          {
            method: "GET",
            redirect,
            headers: {
              "User-Agent": "Mozilla/5.0 (compatible; Maia-Release-Readiness/1.0)",
              Accept: "text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8",
              Range: "bytes=0-0",
              "Accept-Encoding": "identity",
            },
          },
          timeoutMs,
        );

        try {
          res.body?.cancel();
        } catch {}

        const latency_ms = nowMs() - started;
        return {
          url,
          method: "GET",
          ok: res.status >= 200 && res.status < 400,
          status: res.status,
          final_url: String(res.url || url),
          redirected: Boolean(res.redirected),
          latency_ms,
          error: null,
        };
      } catch (e) {
        const latency_ms = nowMs() - started;
        const msg = e instanceof Error ? e.message : String(e);
        const name = e && typeof e === "object" && "name" in e ? String(e.name) : "";
        const isTimeout = name === "AbortError";
        return {
          url,
          method: "GET",
          ok: false,
          status: 0,
          final_url: url,
          redirected: false,
          latency_ms,
          error: isTimeout ? `timeout: ${msg}` : msg,
        };
      }
    });

    return { outputs: { results_patch, meta } };
  },
};

export default {
  async main(env, ctx) {
    const upstream = ctx?.upstream || {};

    const extracted = upstream.extract_links?.data;
    const targets = Array.isArray(extracted?.outputs?.targets) ? extracted.outputs.targets : [];

    const head = upstream.head_check_links?.data;
    const headResults = Array.isArray(head?.outputs?.results) ? head.outputs.results : [];

    const fb = upstream.get_fallback_links?.data;
    const patch = Array.isArray(fb?.outputs?.results_patch) ? fb.outputs.results_patch : [];

    const meta = {
      mergedAt: new Date().toISOString(),
      errors: [],
      warnings: [],
      stats: {
        targets: targets.length,
        headResults: headResults.length,
        fallbackPatched: patch.length,
      },
    };

    const byUrl = new Map();
    for (const r of headResults) {
      const url = String(r?.url || "");
      if (url) byUrl.set(url, r);
    }
    for (const r of patch) {
      const url = String(r?.url || "");
      if (url) byUrl.set(url, r);
    }

    const results = [];
    for (const t of targets) {
      const url = String(t?.url || "");
      const r = byUrl.get(url);
      results.push(
        r || {
          url,
          method: null,
          ok: false,
          status: 0,
          final_url: url,
          redirected: false,
          latency_ms: null,
          error: "missing_result",
        },
      );
    }

    const okCount = results.filter((r) => Boolean(r?.ok)).length;
    const failCount = results.length - okCount;

    const summary = {
      total: results.length,
      ok: okCount,
      failed: failCount,
      top_failed: results.filter((r) => !r.ok).slice(0, 15).map((r) => ({ url: r.url, status: r.status, error: r.error })),
    };

    return { outputs: { summary, results, meta } };
  },
};

function escMd(s) {
  return String(s ?? "").replace(/\|/g, "\\|").replace(/\r?\n/g, " ");
}

function fmtBool(v) {
  return v ? "✅" : "❌";
}

export default {
  async main(env, ctx) {
    const upstream = ctx?.upstream || {};

    const norm = upstream.normalize_repo?.data;
    const repoMeta = upstream.fetch_repo_meta?.data;
    const rel = upstream.fetch_release_info?.data;
    const issues = upstream.fetch_issue_stats?.data;
    const pkg = upstream.analyze_package_json?.data;
    const docs = upstream.fetch_repo_docs?.data;
    const links = upstream.merge_link_results?.data;

    const repo = repoMeta?.outputs?.repo || null;
    const effectiveRef = repoMeta?.outputs?.effective_ref || null;

    const latest_release = rel?.outputs?.latest_release || null;
    const latest_tag = rel?.outputs?.latest_tag || null;

    const issueStats = issues?.outputs?.stats || null;

    const pkgExists = Boolean(pkg?.outputs?.exists);
    const pkgSummary = pkg?.outputs?.summary || null;
    const pkgChecks = Array.isArray(pkg?.outputs?.checks) ? pkg.outputs.checks : [];

    const docFiles = Array.isArray(docs?.outputs?.files) ? docs.outputs.files : [];
    const docOk = docFiles.filter((f) => f?.ok).map((f) => f.path);

    const linkSummary = links?.outputs?.summary || { total: 0, ok: 0, failed: 0, top_failed: [] };
    const linkResults = Array.isArray(links?.outputs?.results) ? links.outputs.results : [];

    const now = new Date().toISOString();

    // Build a structured summary output first (useful for downstream automations)
    const summary_json = {
      generated_at: now,
      repo: {
        input: norm?.outputs?.repo_url || null,
        full_name: repo?.full_name || null,
        default_branch: repo?.default_branch || null,
        effective_ref: effectiveRef,
        visibility: repo?.visibility || null,
        private: repo?.private ?? null,
        archived: repo?.archived ?? null,
        disabled: repo?.disabled ?? null,
        stars: repo?.stargazers_count ?? null,
      },
      release: {
        latest_release,
        latest_tag,
      },
      issues: issueStats,
      docs: {
        fetched_ok: docOk,
        fetched_total: docFiles.length,
      },
      links: linkSummary,
      package_json: {
        exists: pkgExists,
        summary: pkgSummary,
      },
    };

    const lines = [];
    lines.push(`# Open Source Project Release Readiness Report`);
    lines.push("");
    lines.push(`- Generated at: ${now}`);
    if (repo?.full_name) lines.push(`- Repo:${repo.full_name}`);
    if (norm?.outputs?.repo_url) lines.push(`- Repo URL:${norm.outputs.repo_url}`);
    if (effectiveRef) lines.push(`- Check ref: ${effectiveRef}`);
    lines.push("");

    lines.push("## 1) Repository Basic Health");
    lines.push("");
    if (repo) {
      lines.push(`- Private:${fmtBool(Boolean(repo.private))}(private)`);
      lines.push(`- Archived:${fmtBool(Boolean(repo.archived))}(archived)`);
      lines.push(`- Disabled:${fmtBool(Boolean(repo.disabled))}(disabled)`);
      lines.push(`- Stars:${repo.stargazers_count ?? "-"}`);
      lines.push(`- Default branch:${repo.default_branch ?? "-"}`);
      lines.push(`- License:${repo.license?.spdx_id || repo.license?.name || "-"}`);
    } else {
      lines.push("- Failed to fetch repo metadata (may be rate-limited or repo does not exist)");
    }
    lines.push("");

    lines.push("## 2) Release/Tag Status");
    lines.push("");
    if (latest_release) {
      lines.push(`- Latest release:${latest_release.tag_name || "-"}${latest_release.prerelease ? " (prerelease)" : ""}${latest_release.draft ? " (draft)" : ""}`);
      if (latest_release.published_at) lines.push(`- Published at:${latest_release.published_at}`);
      if (latest_release.html_url) lines.push(`- URL: ${latest_release.html_url}`);
    } else {
      lines.push("- No latest release (or fetch failed). This is normal for new projects.")
    }
    if (latest_tag) {
      lines.push(`- Latest tag:${latest_tag.name || "-"}`);
    } else {
      lines.push("- No tags (or fetch failed).")
    }
    lines.push("");

    lines.push("## 3) Issue / PR Snapshot (Real GitHub Search API)");
    lines.push("");
    if (issueStats) {
      lines.push("| Metric | Count |");
      lines.push("| ---- | ---- |");
      for (const [k, v] of Object.entries(issueStats)) {
        lines.push(`| ${escMd(k)} | ${v == null ? "-" : String(v)} |`);
      }
    } else {
      lines.push("- Failed to fetch issue statistics (may be rate-limited; optionally configure GITHUB_TOKEN)");
    }
    lines.push("");

    lines.push("## 4) Key Document Presence (Fetched from Repository)");
    lines.push("");
    lines.push(`- Successfully fetched: ${docOk.length}/${docFiles.length}`);
    if (docOk.length) lines.push(`- Fetched files: ${docOk.map((x) => `\`${x}\``).join(", ")}`);
    lines.push("");

    lines.push("## 5) External Link Availability (Real Requests: HEAD + GET Fallback)");
    lines.push("");
    lines.push(`- Total external links: ${Number(linkSummary.total || 0)}`);
    lines.push(`- Passed: ${Number(linkSummary.ok || 0)}`);
    lines.push(`- Failed: ${Number(linkSummary.failed || 0)}`);

    if (Array.isArray(linkSummary.top_failed) && linkSummary.top_failed.length) {
      lines.push("");
      lines.push("### Failed Examples (Top 15)");
      lines.push("");
      lines.push("| # | URL | Status | Error |");
      lines.push("| - | --- | ------ | ----- |");
      linkSummary.top_failed.forEach((f, i) => {
        lines.push(`| ${i + 1} | ${escMd(f.url)} | ${escMd(f.status)} | ${escMd(f.error)} |`);
      });
    }

    lines.push("");

    lines.push("## 6) package.json Publish/Open Source Field Checks (Optional)");
    lines.push("");
    if (!pkgExists) {
      lines.push("- No package.json in repo root: skipping npm publish-related checks.");
    } else {
      if (pkgSummary) {
        lines.push(`- score:${pkgSummary.score ?? "-"}（errors=${pkgSummary.errors ?? "-"}, warnings=${pkgSummary.warnings ?? "-"}）`);
      }
      if (pkgChecks.length) {
        lines.push("");
        lines.push("| Check | OK | Level | Detail |");
        lines.push("| ----- | -- | ----- | ------ |");
        for (const c of pkgChecks) {
          lines.push(`| ${escMd(c.title)} | ${c.ok ? "✅" : "❌"} | ${escMd(c.level)} | ${escMd(c.detail || "")} |`);
        }
      }
    }

    lines.push("");
    lines.push("## 7) Next Steps Recommendations (Can Follow Directly)");
    lines.push("");
    lines.push("- If many external links fail: first confirm if CI/internal network cannot access external sites; then appropriately reduce concurrency/increase timeout.");
    lines.push("- If GitHub API is frequently rate-limited: configure `GITHUB_TOKEN` in Workflow envJson (read-only public repo access can significantly increase quota).");
    lines.push("- If package.json is missing repository/license/homepage: recommend adding them (critical for open source user experience).");
    lines.push("- If there are no Releases yet: at least create a tag + write a CHANGELOG/Release notes (users will trust more).");

    const report_md = lines.join("\n");

    const meta = {
      builtAt: now,
      wroteFiles: [],
      errors: [],
      warnings: [],
    };

    // Register artifacts
    try {
      const a1 = await ctx.artifacts.writeText("release-readiness-report.md", report_md, {
        kind: "file",
        summary: "Release readiness report (Markdown)",
      });
      meta.wroteFiles.push(a1);
    } catch (e) {
      meta.errors.push(`write report_md failed: ${e instanceof Error ? e.message : String(e)}`);
    }

    try {
      const a2 = await ctx.artifacts.writeText("release-readiness-summary.json", JSON.stringify(summary_json, null, 2), {
        kind: "file",
        summary: "Release readiness summary (JSON)",
      });
      meta.wroteFiles.push(a2);
    } catch (e) {
      meta.errors.push(`write summary_json failed: ${e instanceof Error ? e.message : String(e)}`);
    }

    return {
      outputs: {
        report_md,
        summary_json,
        links_summary: linkSummary,
        links_results: linkResults,
        meta,
      },
    };
  },
};
